// Xevorith NetGuard - Stage 1: Wi-Fi connection (single-file version)
// Board: ESP32C3 Dev Module  |  Serial Monitor: 115200 baud
#include <WiFi.h>
#include <esp_wifi.h>
#include "secrets.h"

// ====== EDIT THESE (use your 2.4 GHz network, not the _5G one) ======
const char* WIFI_SSID     = "Laksubha";
const char* WIFI_PASSWORD = "pradeep369subha";
// =====================================================================

const char* HOSTNAME = "xevorith-netguard";
const uint32_t STATUS_INTERVAL_MS = 10000;
const uint32_t MIN_BACKOFF_MS = 3000;
const uint32_t MAX_BACKOFF_MS = 60000;

// Uncomment if the board connects poorly (weak-antenna workaround):
// #define LOW_TX_POWER

volatile uint8_t lastReason = 0;
volatile bool disconnectPending = false;
uint32_t lastAttemptMs = 0, backoffMs = MIN_BACKOFF_MS, lastStatusMs = 0;
bool wasConnected = false;
uint32_t reconnectCount = 0;

const char* reasonText(uint8_t r) {
  switch (r) {
    case WIFI_REASON_AUTH_EXPIRE:
    case WIFI_REASON_AUTH_FAIL:
    case WIFI_REASON_4WAY_HANDSHAKE_TIMEOUT:
    case WIFI_REASON_HANDSHAKE_TIMEOUT: return "authentication failed (check password)";
    case WIFI_REASON_NO_AP_FOUND:       return "SSID not found (wrong name, or 5 GHz only?)";
    case WIFI_REASON_ASSOC_FAIL:        return "association failed";
    case WIFI_REASON_BEACON_TIMEOUT:    return "beacon timeout (weak signal)";
    case WIFI_REASON_AUTH_LEAVE:
    case WIFI_REASON_ASSOC_LEAVE:       return "router disconnected us";
    case WIFI_REASON_CONNECTION_FAIL:   return "connection failed";
    default:                            return "other";
  }
}

void onWiFiEvent(WiFiEvent_t event, WiFiEventInfo_t info) {
  if (event == ARDUINO_EVENT_WIFI_STA_DISCONNECTED) {
    lastReason = info.wifi_sta_disconnected.reason;
    disconnectPending = true;
  }
}

void startConnect() {
  lastAttemptMs = millis();
  WiFi.disconnect(false);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
}

void printWifiStatus() {
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("[WiFi] Status: NOT connected");
    return;
  }
  Serial.printf("[WiFi] SSID: %s | IP: %s | GW: %s | DNS: %s\n",
                WiFi.SSID().c_str(), WiFi.localIP().toString().c_str(),
                WiFi.gatewayIP().toString().c_str(), WiFi.dnsIP().toString().c_str());
  Serial.printf("[WiFi] MAC: %s | RSSI: %d dBm | Channel: %d\n",
                WiFi.macAddress().c_str(), WiFi.RSSI(), WiFi.channel());
}

void wifiLoop() {
  if (disconnectPending) {
    disconnectPending = false;
    Serial.printf("[WiFi] Disconnected: %s (reason %u)\n", reasonText(lastReason), lastReason);
  }
  if (WiFi.status() == WL_CONNECTED) {
    if (!wasConnected) {
      wasConnected = true;
      backoffMs = MIN_BACKOFF_MS;
      reconnectCount++;
      Serial.printf("[WiFi] Reconnected (reconnect #%lu).\n", (unsigned long)reconnectCount);
      printWifiStatus();
    }
    return;
  }
  wasConnected = false;
  if (millis() - lastAttemptMs >= backoffMs) {
    uint32_t next = backoffMs * 2;
    if (next > MAX_BACKOFF_MS) next = MAX_BACKOFF_MS;
    Serial.printf("[WiFi] Retrying (next wait %lus)...\n", (unsigned long)(next / 1000));
    startConnect();
    backoffMs = next;
  }
}

void setup() {
  Serial.begin(115200);
  uint32_t t = millis();
  while (!Serial && millis() - t < 3000) delay(10);

  Serial.println();
  Serial.println("=== Xevorith NetGuard :: Stage 1 (Wi-Fi) ===");
  Serial.printf("Chip: %s rev %d | CPU: %u MHz | Free heap: %u bytes\n",
                ESP.getChipModel(), ESP.getChipRevision(),
                ESP.getCpuFreqMHz(), ESP.getFreeHeap());

  WiFi.persistent(false);
  WiFi.mode(WIFI_STA);
  WiFi.setHostname(HOSTNAME);
  WiFi.setAutoReconnect(true);
  WiFi.setSleep(false);
  WiFi.onEvent(onWiFiEvent);
#ifdef LOW_TX_POWER
  WiFi.setTxPower(WIFI_POWER_8_5dBm);
#endif

  Serial.printf("[WiFi] Connecting to \"%s\"...\n", WIFI_SSID);
  startConnect();
  uint32_t start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 20000) {
    delay(500);
    Serial.print('.');
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    wasConnected = true;
    disconnectPending = false;
    Serial.println("[WiFi] Connected.");
    printWifiStatus();
  } else if (disconnectPending) {
    Serial.printf("[WiFi] Failed: %s (reason %u)\n", reasonText(lastReason), lastReason);
    disconnectPending = false;
  } else {
    Serial.println("[WiFi] Failed: timed out. Will keep retrying.");
  }
}

void loop() {
  wifiLoop();
  if (millis() - lastStatusMs >= STATUS_INTERVAL_MS) {
    lastStatusMs = millis();
    Serial.printf("[SYS] uptime %lus | heap %u | wifi %s",
                  (unsigned long)(millis() / 1000), ESP.getFreeHeap(),
                  WiFi.status() == WL_CONNECTED ? "UP" : "DOWN");
    if (WiFi.status() == WL_CONNECTED)
      Serial.printf(" | %s | %d dBm", WiFi.localIP().toString().c_str(), WiFi.RSSI());
    Serial.println();
  }
  delay(10);
}
